valores = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

def romano_para_inteiro(s):
    total = 0
    for i, simbolo in enumerate(s):
        if i + 1 < len(s) and valores[simbolo] < valores[s[i + 1]]:
            total -= valores[simbolo]
        else:
            total += valores[simbolo]
    return total

def inteiro_para_romano(n):
    mapa = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
    romano = ""
    for valor, simbolo in mapa:
        while n >= valor:
            romano += simbolo
            n -= valor
    return romano

print(romano_para_inteiro("XIV"))

